import{_ as a,o as e,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/72-“上流”女性味十足，“下流”喜欢颠覆.md","filePath":"books/xialiu-shehui/72-“上流”女性味十足，“下流”喜欢颠覆.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/72-“上流”女性味十足，“下流”喜欢颠覆.md"};function s(i,_,r,n,l,d){return e(),t("div",null,[..._[0]||(_[0]=[o('<h2 id="上流-女性味十足-下流-喜欢颠覆" tabindex="-1">“上流”女性味十足，“下流”喜欢颠覆 <a class="header-anchor" href="#上流-女性味十足-下流-喜欢颠覆" aria-label="Permalink to &quot;“上流”女性味十足，“下流”喜欢颠覆&quot;">​</a></h2><p>但是，上流阶层的女性未必都缺少传统印象当中女性所应有的样子，事实上情况恰恰相反。</p><p>例如，针对“男人应该有男人的样子，女人应该有女人的样子”这一问题，回答“同意”或“基本上同意”的团块次代女性当中，“上流”占29.4%，“中流”占21.1%，而“下流”则仅占16.2%。如果将不拘于传统观念的“颠覆传统派”与“顺应传统派”进行比较的话，“颠覆传统派”的人选择“同意”或“基本上同意”的占15.5%，但“顺应传统派”的人却占到了25.5%。</p><p>对于“女性在结婚后也应该有工作（自己的收入）”这一问题，回答“同意”的女性在上流阶层中只占5.9%，但在中流阶层和下流阶层则分别占到了30.8%和25.8%。同样以这个问题将“颠覆传统派”和“顺应传统派”进行比较的话，则“颠覆传统派”回答“同意”的占17.8%，而“顺应传统派”占25.4%。</p><p>此外，对于“结婚生子后，想工作和照顾孩子两不误”这一问题，回答“同意”的女性在上流阶层中占11.8%，在中流阶层和下流阶层则分别占17.3%和25.8%。</p><p>问到“单身的时候专注于工作，一旦结婚生子以后就想过以家庭为中心的生活”，回答“同意”或“基本上同意”的人在上流阶层中占53%，在中流阶层和下流阶层分别占44.2%和35.5%。</p><p>另一方面，同意“对结婚和工作都不怎么关心，只想按自己的方式生活”的人，在上流阶层中所占的比例为零，在中流阶层和下流阶层则分别占7.7%和22.6%。</p><p>综上所述，阶层越是“上流”的女性，越不屑“颠覆传统”，且越具有传统的男女观念。换句话说，不怎么重视传统的男女观念以及自身形象的女性，往往有着更强烈的反传统志向，阶层意识也更低。</p><p>更进一步说，上流阶层的女性不仅肯定传统的男女观念，同时性格中也颇具领导力，是属于“才色兼备”型的女性。她们是典型的高学历、工作能力强且容貌端庄的女性，然而结婚之后，她们又能成为一名乐于相夫教子，甘愿做家务和养育孩子的称职的专职家庭主妇。</p>',9)])])}const u=a(p,[["render",s]]);export{h as __pageData,u as default};
